<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AdminIcon from './AdminIcon.vue'
type Patient={id:number;full_name:string;nik:string;phone:string;status:string;rt:string;rw:string;treatment_place_id?:number;cadre_id?:number|null;treatment_start_date?:string;tb_diagnosis?:string|null;diagnosis_type?:string|null;daily_dose_frequency?:number;photo_path?:string|null;birth_place?:string;birth_date?:string;gender?:string;full_address?:string;medical_record_number?:string;cadre?:{full_name:string;phone?:string}}
const patients=ref<Patient[]>([]),loading=ref(true),error=ref(''),selected=ref<Patient|null>(null),editing=ref(false),saving=ref(false),stats=ref({total:0,male:0,female:0,under_40:0,over_40:0})
const filterRw=ref(''),filterGender=ref(''),filterAge=ref('')
const rwOptions=computed(()=>[...new Set(patients.value.map(p=>p.rw).filter(Boolean))].sort())
const filteredPatients=computed(()=>patients.value.filter(p=>{const age=p.birth_date?Math.floor((Date.now()-new Date(p.birth_date).getTime())/31557600000):null;return (!filterRw.value||p.rw===filterRw.value)&&(!filterGender.value||p.gender===filterGender.value)&&(!filterAge.value||(filterAge.value==='under40'&&age!==null&&age<40)||(filterAge.value==='over40'&&age!==null&&age>=40))}))
const base='/api/v1',headers={Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'}
const photo=(p:Patient)=>p.photo_path?'/storage/'+p.photo_path:'/icons/icon-512.png'
const formatDate=(value?:string|null)=>{if(!value)return '';const [year,month,day]=value.slice(0,10).split('-');return year&&month&&day?`${day}/${month}/${year}`:value}
const whatsapp=(phone?:string)=>phone?'https://wa.me/'+phone.replace(/[^0-9]/g,''):''
async function load(){try{const r=await fetch(`${base}/patients?per_page=100`,{headers});const p=await r.json();if(!r.ok)throw new Error(p.message);patients.value=p.data;stats.value=p.meta.stats}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat pasien.'}finally{loading.value=false}}
function open(p:Patient){selected.value={...p,birth_date:formatDate(p.birth_date)};editing.value=false}function close(){selected.value=null;editing.value=false}
async function save(){if(!selected.value)return;saving.value=true;try{const r=await fetch(`${base}/patients/${selected.value.id}`,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({full_name:selected.value.full_name,nik:selected.value.nik,birth_place:selected.value.birth_place,birth_date:selected.value.birth_date,gender:selected.value.gender,phone:selected.value.phone,rt:selected.value.rt,rw:selected.value.rw,full_address:selected.value.full_address,treatment_place_id:selected.value.treatment_place_id,cadre_id:selected.value.cadre_id,treatment_start_date:selected.value.treatment_start_date,tb_diagnosis:selected.value.tb_diagnosis,diagnosis_type:selected.value.diagnosis_type,daily_dose_frequency:selected.value.daily_dose_frequency,status:selected.value.status})});const p=await r.json();if(!r.ok)throw new Error(p.message);await load();selected.value=patients.value.find(x=>x.id===selected.value?.id)||null;editing.value=false}catch(e){error.value=e instanceof Error?e.message:'Gagal memperbarui pasien.'}finally{saving.value=false}}
async function remove(){if(!selected.value||!confirm('Hapus data pasien ini?'))return;saving.value=true;try{const r=await fetch(`${base}/patients/${selected.value.id}`,{method:'DELETE',headers});if(!r.ok)throw new Error('Gagal menghapus pasien.');close();await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal menghapus pasien.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><main class="admin-page patients-page"><section class="admin-content"><header><div><p>Manajemen data</p><h1>Data Pasien</h1><p class="page-subtitle">Kelola identitas, kontak, dan status pengobatan pasien.</p></div><a class="add-button" href="/admin/patients/create">+ Tambah Pasien</a></header><section class="patient-stat-grid"><article><AdminIcon name="users"/><div><b>{{stats.total}}</b><span>Total Pasien Aktif</span></div></article><article><AdminIcon name="users"/><div><b>{{stats.male}}</b><span>Laki-laki</span></div></article><article><AdminIcon name="users"/><div><b>{{stats.female}}</b><span>Perempuan</span></div></article><article><AdminIcon name="calendar"/><div><b>{{stats.under_40}}</b><span>Di bawah 40 tahun</span></div></article><article><AdminIcon name="calendar"/><div><b>{{stats.over_40}}</b><span>40 tahun ke atas</span></div></article></section><section class="patient-filters"><label>RW<select v-model="filterRw"><option value="">Semua RW</option><option v-for="rw in rwOptions" :key="rw" :value="rw">RW {{rw}}</option></select></label><label>Jenis kelamin<select v-model="filterGender"><option value="">Semua jenis kelamin</option><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label><label>Usia<select v-model="filterAge"><option value="">Semua usia</option><option value="under40">Di bawah 40 tahun</option><option value="over40">40 tahun ke atas</option></select></label><button type="button" class="clear-filter" @click="filterRw='';filterGender='';filterAge=''">Reset filter</button></section><section class="panel"><p v-if="loading">Memuat data pasien…</p><p v-else-if="error" class="login-error">{{error}}</p><div v-else class="table-scroll"><table><thead><tr><th>Foto</th><th>Nama Pasien</th><th>NIK</th><th>No. HP</th><th>Diagnosis TBC</th><th>Tipe Diagnosis</th><th>RT</th><th>RW</th><th>Kader</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-if="!filteredPatients.length"><td colspan="11" class="empty">Belum ada pasien.</td></tr><tr v-for="patient in filteredPatients" :key="patient.id"><td><img class="patient-thumb" :src="photo(patient)" alt=""/></td><td><b>{{patient.full_name}}</b><small>{{patient.medical_record_number||'No. RM belum tersedia'}}</small></td><td>{{patient.nik}}</td><td><span>{{patient.phone}}</span><a v-if="whatsapp(patient.phone)" class="whatsapp-button" :href="whatsapp(patient.phone)" target="_blank" rel="noopener">WhatsApp</a></td><td>{{patient.tb_diagnosis||'—'}}</td><td>{{patient.diagnosis_type||'—'}}</td><td>{{patient.rt}}</td><td>{{patient.rw}}</td><td><span>{{patient.cadre?.full_name||'Belum ditetapkan'}}</span><a v-if="patient.cadre?.phone" class="whatsapp-button kader-wa" :href="whatsapp(patient.cadre.phone)" target="_blank" rel="noopener">WhatsApp</a></td><td><span class="status pending">{{patient.status}}</span></td><td><button class="view-button" @click="open(patient)">Lihat</button></td></tr></tbody></table></div></section></section><div v-if="selected" class="detail-backdrop" @click.self="close"><section class="patient-detail" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button class="detail-close" @click="close" aria-label="Tutup">×</button><div class="detail-hero"><img :src="photo(selected)" alt="Foto profil pasien"/><div><small>Profil pasien</small><h2 id="detail-title">{{selected.full_name}}</h2><span class="status pending">{{selected.status}}</span></div></div><div v-if="editing" class="detail-edit"><label>Nama lengkap<input v-model="selected.full_name"/></label><label>NIK<input v-model="selected.nik"/></label><label>Tempat lahir<input v-model="selected.birth_place"/></label><label>Tanggal lahir<input v-model="selected.birth_date" type="date"/></label><label>Jenis kelamin<select v-model="selected.gender"><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label><label>No. HP<input v-model="selected.phone"/></label><label>RT<input v-model="selected.rt"/></label><label>RW<input v-model="selected.rw"/></label><label>Tempat pengobatan<input v-model="selected.treatment_place_id" type="number"/></label><label>Diagnosis TBC<select v-model="selected.tb_diagnosis"><option value="">Pilih diagnosis TBC</option><option value="TB Paru">TB Paru</option><option value="TB Ekstraparu">TB Ekstraparu</option></select></label><label>Tipe diagnosis<select v-model="selected.diagnosis_type"><option value="">Pilih tipe diagnosis</option><option value="Bakteriologis">Bakteriologis</option><option value="Klinis">Klinis</option></select></label><label>Tanggal mulai pengobatan<input v-model="selected.treatment_start_date" type="date"/></label><label>Frekuensi obat per hari<input v-model.number="selected.daily_dose_frequency" type="number" min="1" max="6"/></label><label>Status<select v-model="selected.status"><option value="active">Aktif</option><option value="paused">Ditunda</option><option value="completed">Selesai</option></select></label><label class="wide">Alamat<textarea v-model="selected.full_address"/></label></div><dl v-else class="detail-grid"><div><dt>NIK</dt><dd>{{selected.nik}}</dd></div><div><dt>No. Rekam Medis</dt><dd>{{selected.medical_record_number||'Belum tersedia'}}</dd></div><div><dt>Tanggal Lahir</dt><dd>{{selected.birth_date||'Belum tersedia'}}</dd></div><div><dt>Jenis Kelamin</dt><dd>{{selected.gender==='L'?'Laki-laki':'Perempuan'}}</dd></div><div><dt>Diagnosis TBC</dt><dd>{{selected.tb_diagnosis||'Belum tersedia'}}</dd></div><div><dt>Tipe diagnosis</dt><dd>{{selected.diagnosis_type||'Belum tersedia'}}</dd></div><div><dt>No. HP</dt><dd>{{selected.phone}} <a class="whatsapp-button" :href="whatsapp(selected.phone)" target="_blank" rel="noopener">WhatsApp</a></dd></div><div><dt>Kader PMO</dt><dd>{{selected.cadre?.full_name||'Belum ditetapkan'}}<a v-if="selected.cadre?.phone" class="whatsapp-button kader-wa" :href="whatsapp(selected.cadre.phone)" target="_blank" rel="noopener">WhatsApp kader</a></dd></div><div class="wide"><dt>Alamat</dt><dd>{{selected.full_address||'Belum tersedia'}}</dd></div></dl><div class="detail-actions"><template v-if="editing"><button class="secondary-button" @click="editing=false">Batal</button><button class="save-button" :disabled="saving" @click="save">{{saving?'Menyimpan…':'Simpan perubahan'}}</button></template><template v-else><button class="secondary-button" @click="editing=true">Edit</button><button class="danger-button" :disabled="saving" @click="remove">Hapus pasien</button></template></div></section></div></main></template>
<style scoped>
