op:18px}.danger-button{border:1px solid #efb6b0;background:#fff1ef;color:#b53b30;border-radius:7px;padding:8px 13px;font-weight:bold;cursor:pointer}.save-button{cursor:pointer}@media(max-width:700px){.patient-detail{padding:20px}.detail-grid,.detail-edit{grid-template-columns:1fr}.detail-grid .wide,.detail-edit textarea{grid-column:auto}}
</style><style scoped>.patient-filters{display:flex;align-items:end;gap:14px;flex-wrap:wrap;margin:18px 0}.patient-filters label{display:block;font-size:12px;font-weight:bold}.patient-filters select{display:block;margin-top:6px;padding:10px;border:1px solid #cfe2de;border-radius:8px;background:#fff}.clear-filter{padding:10px 14px;border:1px solid #b7ddd4;border-radius:8px;background:#edf9f6;color:#087e78;cursor:pointer}</style><style scoped>.whatsapp-button{display:block;width:max-content;margin-top:5px;padding:4px 8px;border-radius:6px;background:#dff7e9;color:#128a4e;text-decoration:none;font-size:10px;font-weight:bold}.whatsapp-button:hover{background:#bdf0d1}.detail-grid .whatsapp-button{display:inline-block;margin-left:7px}.kader-wa{font-size:9px}</style><style scoped>.patient-stat-grid article{display:flex;align-items:center;gap:13px}.patient-stat-grid .admin-png-icon{width:40px;height:40px;padding:6px;border-radius:12px;background:#e4f8f2}.patient-stat-grid article:nth-child(2) .admin-png-icon{background:#e8f5ff}.patient-stat-grid article:nth-child(3) .admin-png-icon{background:#fff0f2}.patient-stat-grid article:nth-child(4) .admin-png-icon,.patient-stat-grid article:nth-child(5) .admin-png-icon{background:#f0ebff}.patient-stat-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:18px 0}.patient-stat-grid article{padding:18px;background:#fff;border:1px solid #dfedeb;border-radius:12px;box-shadow:0 6px 16px #28766b0b}.patient-stat-grid b{display:block;font-size:28px;color:#087e78}.patient-stat-grid span{font-size:11px;color:#6d8990}@media(max-width:1000px){.patient-stat-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){.patient-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
